// Support for Raven's actors (raven/trusted/actors.rook): the arena they live in,
// and the jump from the scheduler into an actor's dispatcher.

    .section .text

// void call_dispatch(dispatcher, actor, handler, payload)
//
// Jumps to an actor's dispatcher (generated by Fledgling, see Gen.dispatcher)
// with the arguments it expects: x0 = actor, x1 = handler number, x2 = the address
// of the message's payload words. The dispatcher returns to our caller.
    .global call_dispatch
call_dispatch:
    mov     x16, x0                     // the dispatcher's address
    mov     x0, x1
    mov     x1, x2
    mov     x2, x3
    br      x16

// u64 call_protected(dispatcher, actor, handler, payload)
//
// Calls a handler (or an actor's start stub) so that a failure inside it, a panic or an
// overrun of the time budget, can abandon it: `actor_failed` below jumps back here as if
// the call had returned, with 1 in x0 (0 if it returned normally). Registers the caller
// keeps (x19-x28, x29, sp) are saved in the arena (offset 1728) and put back. One
// protected call at a time (handlers run to completion, decision 121), and the flag at
// offset 1088 says whether one is running.
    .global call_protected
call_protected:
    stp     x29, x30, [sp, #-16]!
    mov     x29, sp
    mrs     x9, tpidr_el1               // this core's actor arena (T_ARENA in domain.s)
    ldr     x9, [x9, #176]
    add     x10, x9, #1728
    stp     x19, x20, [x10, #0]
    stp     x21, x22, [x10, #16]
    stp     x23, x24, [x10, #32]
    stp     x25, x26, [x10, #48]
    stp     x27, x28, [x10, #64]
    str     x29, [x10, #80]             // sp as it is now (x29 was set from it)
    mov     x11, #1
    str     x11, [x9, #1088]            // a protected call is running
    mov     x16, x0                     // the dispatcher's address
    mov     x0, x1
    mov     x1, x2
    mov     x2, x3
    blr     x16
    mov     x0, #0                      // it returned
protected_exit:
    mrs     x9, tpidr_el1               // this core's actor arena (T_ARENA in domain.s)
    ldr     x9, [x9, #176]
    str     xzr, [x9, #1088]
    ldp     x29, x30, [sp], #16
    ret

// void actor_failed(void): never returns to its caller. If a protected call is running,
// abandons it: unmasks IRQs (it may be called from the budget interrupt), puts back the
// registers and the stack that call_protected saved, and returns 1 from it. Otherwise
// (a panic outside any handler, in kernel_main or a test program) halts the core as a
// panic always did.
    .global actor_failed
actor_failed:
    mrs     x9, tpidr_el1               // this core's actor arena (T_ARENA in domain.s)
    ldr     x9, [x9, #176]
    ldr     x11, [x9, #1088]
    cbz     x11, 1f
    msr     daifclr, #2
    add     x10, x9, #1728
    ldp     x19, x20, [x10, #0]
    ldp     x21, x22, [x10, #16]
    ldp     x23, x24, [x10, #32]
    ldp     x25, x26, [x10, #48]
    ldp     x27, x28, [x10, #64]
    ldr     x29, [x10, #80]
    mov     sp, x29
    mov     x0, #1
    b       protected_exit
1:  wfe
    b       1b

// u64 handler_table_start(void), u64 handler_table_end(void): the table Fledgling
// writes of every handler (see Gen.handler_table), to name one that overran.
    .global handler_table_start
handler_table_start:
    adrp    x0, rook_handler_table
    add     x0, x0, :lo12:rook_handler_table
    ret

    .global handler_table_end
handler_table_end:
    adrp    x0, rook_handler_table_end
    add     x0, x0, :lo12:rook_handler_table_end
    ret

// void irq_init(void): lets the physical timer interrupt the core, and unmasks IRQs.
// The Pi's per-core interrupt controller (ARM local peripherals, 0x40000000) routes
// the non-secure physical timer, bit 1 of CORE0_TIMER_IRQCNTL (0x40000040), to the
// core's IRQ; each core has its own register, 4 bytes on from the last (decision 178).
    .global irq_init
irq_init:
    msr     cntp_ctl_el0, xzr           // the timer starts disarmed
    ldr     x0, =0x40000040             // CORE0_TIMER_IRQCNTL; core n's is 4 * n further
    mrs     x2, mpidr_el1
    and     x2, x2, #3
    add     x0, x0, x2, lsl #2
    mov     w1, #10                     // nCNTPNSIRQ (bit 1) and nCNTVIRQ (bit 3) -> IRQ. The virtual timer is the idle
    str     w1, [x0]                    // backstop of idle_until_interrupt, below
    ldr     x0, =0x40000050             // CORE0_MBOX_IRQCNTL; core n's is 4 * n further
    add     x0, x0, x2, lsl #2
    mov     w1, #1                      // mailbox 0 -> IRQ: how another core wakes this one from `wfi` (rings.s)
    str     w1, [x0]
    msr     daifclr, #2                 // unmask IRQ
    isb
    ret

// void irq_enable_source(u64 line): lets peripheral interrupt `line` (32 to 63) through
// the Pi's interrupt controller (IRQ enable 2, 0x3F00B214).
    .global irq_enable_source
irq_enable_source:
    sub     x0, x0, #32
    mov     w1, #1
    lsl     w1, w1, w0
    ldr     x2, =0x3F00B214
    str     w1, [x2]
    ret

// u64 irq_take_pending(void): the sources that have fired since the last call (bit
// n is line 32 + n), and clears them. IRQs are masked meanwhile, so one landing
// halfway can't be lost.
    .global irq_take_pending
irq_take_pending:
    msr     daifset, #2
    mrs     x1, tpidr_el1               // this core's actor arena (T_ARENA in domain.s)
    ldr     x1, [x1, #176]
    ldr     x0, [x1, #48]
    str     xzr, [x1, #48]
    msr     daifclr, #2
    ret

// void idle_until_interrupt(void): sleeps until an interrupt arrives, unless one
// already has. Masks IRQs while it looks, because `wfi` wakes for a pending
// interrupt even when it is masked, so none can slip between the look and the sleep. A record in a ring for this core
// raises its mailbox 0 interrupt (rings.s), so it wakes too (decision 183). (`wfe` would wake for the `sev` as well but
// QEMU runs a core in `wfe` as a busy thread: harness/idle_sleeps.)
    .global idle_until_interrupt
idle_until_interrupt:
    msr     daifset, #2
    mrs     x1, tpidr_el1               // this core's actor arena (T_ARENA in domain.s)
    ldr     x1, [x1, #176]
    ldr     x0, [x1, #48]
    cbnz    x0, 1f
    mrs     x2, cntfrq_el0              // a backstop: the virtual timer wakes the core after 1 ms in any case. QEMU was seen
    mov     x3, #1000                   // to leave a core in `wfi` with the mailbox interrupt pending (decision 183), and a
    udiv    x2, x2, x3                  // wake-up that waits for one event is fragile; this costs a thousand wake-ups a
    msr     cntv_tval_el0, x2           // second on an idle core 0 and bounds the latency of a ring record
    mov     x2, #1                      // ENABLE, not masked
    msr     cntv_ctl_el0, x2
    isb
    wfi
    msr     cntv_ctl_el0, xzr           // (the interrupt, if it was this timer, is taken at the `daifclr` below, and finds
    isb                                 // nothing: vectors.s goes on)
1:  msr     daifclr, #2
    ret

// void timer_arm(u64 ticks): interrupt after `ticks` counts of the generic timer.
    .global timer_arm
timer_arm:
    msr     cntp_tval_el0, x0
    mov     x1, #1                      // ENABLE, interrupt not masked
    msr     cntp_ctl_el0, x1
    isb
    ret

// void timer_disarm(void)
    .global timer_disarm
timer_disarm:
    msr     cntp_ctl_el0, xzr
    isb
    ret

// u64 actor_arena_base(void), u64 actor_arena_limit(void): the memory every
// actor, mailbox and Raven's actor tables are carved from.
    .global actor_arena_base
actor_arena_base:
    mrs     x0, tpidr_el1               // this core's actor arena (T_ARENA in domain.s)
    ldr     x0, [x0, #176]
    ret

// u64 raven_arena_address(void): the address of core 0's actor arena, as a constant (no system register is read, so
// a domain can call it too: tests use it as an address a domain must not reach). actor_arena_base is this core's.
    .global raven_arena_address
raven_arena_address:
    adrp    x0, actor_arena
    add     x0, x0, :lo12:actor_arena
    ret

    .global actor_arena_limit
actor_arena_limit:
    mrs     x0, tpidr_el1
    ldr     x0, [x0, #176]
    add     x0, x0, #65536
    ret

    .section .bss
    .balign 4096
    .global actor_arena                 // domains_init gives core n the arena at actor_arena + 64 KB * n
actor_arena:
    .space  4 * 65536                   // 64 KB for each of the four cores; zeroed at boot with the rest of .bss
